// BW-SHIFT-HOURS v1 – server-side business-hours check for employeeShifts create/update.
// Runs inside the "Validate employee shift" request-interception workflow (JavaScript node).
// Arguments: values (request values), filterByTk (record id on update), saved (current record, loaded by id),
//            cfg (systemSettings.options; business hours live in cfg.bwBusinessHours).
// The workflow sandbox has no Intl, so the business timezone is applied with its standard UTC offset plus US DST rules.
const C = Object.assign({ open: '07:00', close: '19:00', stepMinutes: 30, stdOffsetMinutes: -360, dst: 'US' }, (cfg && cfg.bwBusinessHours) || {});
const hm = (s) => { const p = String(s).split(':'); return Number(p[0]) * 60 + Number(p[1] || 0); };
const OPEN = hm(C.open);
const CLOSE = hm(C.close);
const STEP = Number(C.stepMinutes) || 30;
const label = (m) => { const h = Math.floor(m / 60); const mi = Math.round(m % 60); return ((h % 12) || 12) + ':' + String(mi).padStart(2, '0') + ' ' + (h < 12 ? 'AM' : 'PM'); };
const firstOfMonthDow = (y, mon) => new Date(Date.UTC(y, mon, 1)).getUTCDay();
const nthSunday = (y, mon, n) => 1 + ((7 - firstOfMonthDow(y, mon)) % 7) + 7 * (n - 1);
const offsetAt = (ms) => {
  const std = Number(C.stdOffsetMinutes) || 0;
  if (C.dst !== 'US') return std;
  const y = new Date(ms + std * 60000).getUTCFullYear();
  const dstStart = Date.UTC(y, 2, nthSunday(y, 2, 2), 2) - std * 60000;         // 2:00 AM standard time
  const dstEnd = Date.UTC(y, 10, nthSunday(y, 10, 1), 2) - (std + 60) * 60000;  // 2:00 AM daylight time
  return ms >= dstStart && ms < dstEnd ? std + 60 : std;
};
const local = (v) => {
  const ms = new Date(v).getTime();
  if (Number.isNaN(ms)) return null;
  const d = new Date(ms + offsetAt(ms) * 60000);
  return { ms, ymd: d.toISOString().slice(0, 10), min: d.getUTCHours() * 60 + d.getUTCMinutes() + d.getUTCSeconds() / 60 + d.getUTCMilliseconds() / 60000 };
};
const present = (x) => x !== undefined && x !== null && x !== '';
const v = values || {};
const isUpdate = present(filterByTk);
const rec = isUpdate && saved && String(saved.id) === String(filterByTk) ? saved : null;
if (!present(v.startTime) && !present(v.endTime)) return { ok: true, reason: 'times not changed' };
const startRaw = present(v.startTime) ? v.startTime : rec && rec.startTime;
const endRaw = present(v.endTime) ? v.endTime : rec && rec.endTime;
if (!present(startRaw) || !present(endRaw)) return { ok: true, reason: 'incomplete, left to the other checks' };
const s = local(startRaw);
const e = local(endRaw);
if (!s || !e) return { ok: false, message: 'Please enter a valid start and end time.' };
if (rec && present(rec.startTime) && present(rec.endTime) && new Date(rec.startTime).getTime() === s.ms && new Date(rec.endTime).getTime() === e.ms) {
  return { ok: true, reason: 'times unchanged (existing shift kept as saved)' };
}
const fail = (message) => ({ ok: false, message });
if (s.min < OPEN) return fail('Shifts cannot start before ' + label(OPEN) + '.');
if (s.min >= CLOSE) return fail('Shifts must start before ' + label(CLOSE) + '.');
if (e.ms <= s.ms) return fail('Shift end time must be later than start time.');
if (e.ymd !== s.ymd) return fail('Shifts cannot cross midnight. Shifts must end by ' + label(CLOSE) + '.');
if (e.min > CLOSE) return fail('Shifts must end by ' + label(CLOSE) + '.');
if ((e.ms - s.ms) / 60000 < STEP) return fail('Shifts must be at least ' + STEP + ' minutes long.');
if (present(v.shiftDate) && String(v.shiftDate).slice(0, 10) !== s.ymd) return fail('The shift date must be the same day as the start time.');
return { ok: true };

