};
const present = (x) => x !== undefined && x !== null && x !== '';
const v = values || {};
const isUpdate = present(filterByTk);
const rec = isUpdate && saved && String(saved.id) === String(filterByTk) ? saved : null;
if (!present(v.startTime) && !present(v.endTime)) return { ok: true, reason: 'times not changed' };
const startRaw = present(v.startTime) ? v.startTime : rec && rec.startTime;
const endRaw = present(v.endTime) ? v.endTime : rec && rec.endTime;
if (!present(startRaw) || !present(endRaw)) return { ok: true, reason: 'incomplete, left to the other checks' };
const s = local(startRaw);
const e = local(endRaw);
if (!s || !e) return { ok: false, message: 'Please enter a valid start and end time.' };
