if (e.ymd !== s.ymd) return fail('Appointments cannot cross midnight. Appointments must end by ' + label(CLOSE) + '.');
if (e.min > CLOSE) return fail('Appointments must end by ' + label(CLOSE) + '. Choose an earlier start time or fewer services.');
return { ok: true };

// BW-MANAGER-GUARD v1 – server-side limits on user accounts for the Manager role.
// Runs in the "Users: manager account limits" request-interception workflow (users create/update).
// Arguments: roleName (role used for the request), userId (who is making the request),
//            filterByTk (target user on update), filter (bulk-update filter), values (request values),
//            target (target user with roles).
// Other roles are not affected (Admin and Root keep full user management).
const ALLOWED_ROLES = ['r_receptionist', 'r_staff', 'member'];
const PROTECTED_ROLES = ['root', 'admin', 'manager'];
if (roleName !== 'manager') return { ok: true, reason: 'not a manager request' };
const present = (x) => x !== undefined && x !== null && x !== '';
const v = values || {};
const roleNamesOf = (list) => (Array.isArray(list) ? list : [list]).filter(present)
  .map((r) => (typeof r === 'object' ? (r.name || r.id || r.value) : r)).map(String);
const fail = (message) => ({ ok: false, message });
const isUpdate = present(filterByTk);
if (!isUpdate && filter && Object.keys(filter).length) return fail('Managers can only update one user at a time.');
if (isUpdate && String(filterByTk) === String(userId) && Object.prototype.hasOwnProperty.call(v, 'roles')) {
  return fail('You cannot change your own roles. Ask an administrator.');
}
if (isUpdate) {
  const targetRoles = roleNamesOf((target && target.roles) || []);
  if (!target || String(target.id) !== String(filterByTk)) return fail('User not found.');
  if (targetRoles.some((r) => PROTECTED_ROLES.includes(r)) && String(filterByTk) !== String(userId)) {
    return fail('Managers cannot change Admin, Root or Manager accounts. Ask an administrator.');
  }
}
if (Object.prototype.hasOwnProperty.call(v, 'roles')) {
  const wanted = roleNamesOf(v.roles || []);
  const bad = wanted.filter((r) => !ALLOWED_ROLES.includes(r));
  if (bad.length) return fail('Managers can only assign the Receptionist, Staff or Member roles.');
}
return { ok: true };

// BW-CONSENT-GUARD v1 – server-side validation for new communication consent events.
// Arguments: values (request values), roleName (role used for the request), customer (the customer, if found),
//            suppressions (active suppressions for that customer).
const v = values || {};
const fail = (message) => ({ ok: false, message });
const CHANNELS = ['email', 'sms', 'all'];
const PURPOSES = ['marketing', 'transactional', 'all'];
const SOURCES = ['form', 'customer_request', 'staff', 'import', 'provider', 'unsubscribe_link', 'stop_keyword', 'system'];
const GRANT_SOURCES = ['form', 'customer_request', 'import', 'provider'];
const GRANT_ROLES = ['root', 'admin', 'manager'];
const has = (x) => x !== undefined && x !== null && String(x).trim() !== '';
if (!customer || !customer.id) return fail('Choose the customer this consent event belongs to.');
if (!CHANNELS.includes(v.channel)) return fail('Channel must be Email or SMS.');
if (!PURPOSES.includes(v.purpose)) return fail('Purpose must be Marketing or Transactional.');
if (v.action !== 'granted' && v.action !== 'withdrawn') return fail('Action must be Granted or Withdrawn.');
if (!SOURCES.includes(v.consentSource)) return fail('Choose where this consent decision came from.');
if (has(v.recordedAt) && Date.parse(v.recordedAt) > Date.now() + 5 * 60000) return fail('The consent time cannot be in the future.');
if (v.action === 'withdrawn') return { ok: true };
// Granting consent
if (v.channel === 'all' || v.purpose === 'all') return fail('Consent must be granted for one channel and one purpose at a time.');
if (!GRANT_ROLES.includes(roleName)) return fail('Only an Admin or Manager can record that a customer gave consent. You can record an opt-out.');
if (!GRANT_SOURCES.includes(v.consentSource)) return fail('Consent must come from a form, a customer request, an import or a messaging provider.');
if (!has(v.consentTextVersion)) return fail('Record which consent wording the customer agreed to (consent text version).');
if (!has(v.evidenceReference)) return fail('Record the evidence for this consent (for example a signed form number or submission id).');
if (v.channel === 'email' && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(customer.email || '').trim())) return fail('This customer has no usable email address.');
if (v.channel === 'sms' && String(customer.phone || '').replace(/\D/g, '').length < 7) return fail('This customer has no usable phone number.');
const blocked = (suppressions || []).filter((s) => s && s.active !== false && (s.channel === v.channel || s.channel === 'all') && (s.purpose === v.purpose || s.purpose === 'all'));
if (blocked.length) return fail('This customer opted out of these messages. A manager must lift the suppression, with evidence, before consent can be granted again.');
return { ok: true };

// BW-CONSENT-APPLY v1 – turns one consent event into the customer's current preferences.
// Only the channel(s) and purpose(s) named by the event change; every other preference keeps its value.
// Arguments: event (the new consent event), customer (current customer record).
const e = event || {};
const c = customer || {};
const F = {
  email: { marketing: ['emailMarketingOptIn', 'emailMarketingOptInAt'], transactional: ['emailTransactionalOptIn', 'emailTransactionalOptInAt'] },
  sms: { marketing: ['smsMarketingOptIn', 'smsMarketingOptInAt'], transactional: ['smsTransactionalOptIn', 'smsTransactionalOptInAt'] },
};
const out = {};
for (const ch of ['email', 'sms']) for (const pu of ['marketing', 'transactional']) { const [flag, at] = F[ch][pu]; out[flag] = c[flag] === true; out[at] = c[at] || null; }
const when = e.recordedAt || e.createdAt || new Date().toISOString();
const channels = e.channel === 'all' ? ['email', 'sms'] : [e.channel];
const purposes = e.purpose === 'all' ? ['marketing', 'transactional'] : [e.purpose];
for (const ch of channels) for (const pu of purposes) {
  if (!F[ch] || !F[ch][pu]) continue;
  const [flag, at] = F[ch][pu];
  if (e.action === 'granted') { out[flag] = true; out[at] = when; }
  if (e.action === 'withdrawn') { out[flag] = false; out[at] = null; }
}
out.recordedAt = when;
out.suppress = e.action === 'withdrawn';
out.reason = e.consentSource === 'unsubscribe_link' ? 'unsubscribe' : e.consentSource === 'stop_keyword' ? 'stop_keyword' : e.consentSource === 'staff' ? 'staff_recorded' : 'withdrawn';
return out;

// BW-EMAIL-NORMALIZE v1 – trims and lowercases a customer's email; empty becomes null.
const raw = email === undefined || email === null ? null : String(email);
const norm = raw === null ? null : raw.trim().toLowerCase() || null;
return { email: norm, changed: norm !== raw };

// BW-SUPPRESSION-GUARD v1 – communication_suppressions create/update (destroy is always refused).
// Arguments: values, filterByTk, roleName.
const v = values || {};
const fail = (message) => ({ ok: false, message });
const has = (x) => x !== undefined && x !== null && String(x).trim() !== '';
if (!['root', 'admin', 'manager'].includes(roleName)) return fail('Only an Admin or Manager can change suppressions. Record an opt-out in Communication Preferences instead.');
const isUpdate = has(filterByTk);
if (!isUpdate) {
  if (!has(v.customerId) && !(v.customer && has(v.customer.id))) return fail('Choose the customer.');
  if (!['email', 'sms', 'all'].includes(v.channel)) return fail('Channel must be Email, SMS or All channels.');
  if (!['marketing', 'transactional', 'all'].includes(v.purpose)) return fail('Purpose must be Marketing, Transactional or All purposes.');
  if (!has(v.reason)) return fail('Choose a reason.');
  if (v.active === false) return fail('A new suppression must be active.');
  return { ok: true };
}
// Updates may only lift a suppression (with evidence) or add notes.
const allowed = ['active', 'liftedAt', 'liftEvidenceReference', 'notes', 'updatedAt', 'updatedById', 'updatedBy', 'id'];
const extra = Object.keys(v).filter((k) => !allowed.includes(k));
if (extra.length) return fail('Only the lift details and notes of a suppression can be changed.');
if (v.active === true) return fail('A lifted suppression cannot be re-activated; create a new suppression instead.');
if (v.active === false && !has(v.liftEvidenceReference)) return fail('Record the evidence for lifting this suppression (for example the customer\'s written re-subscription).');
return { ok: true };

// BW-CUSTOMER-GUARD v2 – customers create/update.
// Consent preferences change only through consent events; emails must be valid and unique (case-insensitive).
// Arguments: values (request values), filterByTk (customer id on update), current (stored customer on update).
// v2: edit forms send every field back, so on update a preference is refused only when its value differs.
const v = values || {};
const fail = (message) => ({ ok: false, message, email: '', excludeId: '0' });
const FLAGS = ['emailMarketingOptIn', 'emailTransactionalOptIn', 'smsMarketingOptIn', 'smsTransactionalOptIn'];
const TIMES = ['emailMarketingOptInAt', 'emailTransactionalOptInAt', 'smsMarketingOptInAt', 'smsTransactionalOptInAt'];
const isUpdate = filterByTk !== undefined && filterByTk !== null && filterByTk !== '';
const cur = current || {};
const sameTime = (a, b) => { const ea = a === undefined || a === null || a === ''; const eb = b === undefined || b === null || b === ''; if (ea || eb) return ea && eb; return Date.parse(a) === Date.parse(b); };
for (const k of FLAGS) {
  if (!Object.prototype.hasOwnProperty.call(v, k)) continue;
  const want = v[k] === true;
  const have = isUpdate ? cur[k] === true : false;
  if (want !== have) return fail('Communication preferences can only be changed by recording consent in Communication Preferences.');
}
for (const k of TIMES) {
  if (!Object.prototype.hasOwnProperty.call(v, k)) continue;
  if (!sameTime(v[k], isUpdate ? cur[k] : null)) return fail('Communication preferences can only be changed by recording consent in Communication Preferences.');
}
let email = '';
if (Object.prototype.hasOwnProperty.call(v, 'email') && v.email !== null && v.email !== undefined) {
  email = String(v.email).trim().toLowerCase();
  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return fail('Enter a valid email address, for example name@example.com.');
}
return { ok: true, email, excludeId: isUpdate ? String(filterByTk) : '0' };
